package com.vit.archds.entity;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="requirements",indexes=@Index(name="idx_requirements_project",columnList="project_id"))
public class Requirement { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="project_id",nullable=false) private Project project; @Column(length=12000) private String functionalRequirements; @Column(length=12000) private String nonFunctionalRequirements; @Column(length=8000) private String constraints; @Column(length=4000) private String technologyPreferences; @Column(length=500) private String expectedUsers; @Column(length=500) private String budget; @Column(length=4000) private String qualityWeightsJson; @Column private Integer alternatives=5; @Column private Integer maxIterations=5; @Column(nullable=false) private Instant createdAt=Instant.now();
 public Requirement(){} public Requirement(Project p,String f,String n,String c,String t,String u,String b,String w,Integer a,Integer m){project=p;functionalRequirements=f;nonFunctionalRequirements=n;constraints=c;technologyPreferences=t;expectedUsers=u;budget=b;qualityWeightsJson=w;alternatives=a==null?5:a;maxIterations=m==null?5:m;} public Long getId(){return id;} public Project getProject(){return project;} public String getFunctionalRequirements(){return functionalRequirements;} public String getNonFunctionalRequirements(){return nonFunctionalRequirements;} public String getConstraints(){return constraints;} public String getTechnologyPreferences(){return technologyPreferences;} public String getExpectedUsers(){return expectedUsers;} public String getBudget(){return budget;} public String getQualityWeightsJson(){return qualityWeightsJson;} public Integer getAlternatives(){return alternatives;} public Integer getMaxIterations(){return maxIterations;} public Instant getCreatedAt(){return createdAt;}}
